/* 列表搜索/状态/分页及数据行绑定；页面标题、表头、表单与布局由各HTML维护。 */
window.EamList=function(records,options,root=document){const find=id=>[...root.querySelectorAll("[id]")].find(el=>el.id===id||el.dataset.localId===id);const value=id=>find(id)?.value||"";const checked=id=>!!find(id)?.checked;const text=(id,v)=>{const el=find(id);if(el)el.textContent=v;};const rows=find('list-rows');if(!rows)return;records=EamArchiveContext.filter(records,location.search);let page=1;const headers=[...root.querySelectorAll('thead th')].map(h=>h.textContent);const statuses=[...new Set(records.map(r=>r.status))];const select=find('list-status');for(const status of statuses)select.add(new Option(EamProduct.label(status),status));
 function render(){EamUiComponents.decoratePagination();const q=value('list-search').toLowerCase(),status=value('list-status'),mine=checked('list-mine');const filtered=records.filter(r=>(!q||r.values.join(' ').toLowerCase().includes(q))&&(!status||r.status===status)&&(!mine||r.person===Eam.s.person));const pages=Math.max(1,Math.ceil(filtered.length/5));page=Math.min(page,pages);rows.replaceChildren();const SB={pending:'text-bg-warning',in_progress:'text-bg-primary',progress:'text-bg-primary',resolved:'text-bg-success',closed:'text-bg-secondary',complete:'text-bg-success',reopened:'text-bg-info',rejected:'text-bg-danger',draft:'text-bg-light',cancelled:'text-bg-secondary',withdrawn:'text-bg-secondary',archived:'text-bg-secondary',active:'text-bg-success',disabled:'text-bg-secondary',normal:'text-bg-secondary',open:'text-bg-warning',new:'text-bg-primary',review:'text-bg-info'};for(const record of filtered.slice((page-1)*5,page*5)){const tr=document.createElement('tr');record.values.forEach((value,i)=>{const td=document.createElement('td');td.dataset.label=headers[i];if(i===record.values.length-1&&record.status){const badge=document.createElement('span');badge.className='badge rounded-pill '+(SB[record.status]||'text-bg-secondary');badge.textContent=value;td.append(badge);}else td.textContent=value||'未维护';tr.append(td);});const td=document.createElement('td');td.dataset.label='操作';const b=document.createElement('button');b.type='button';b.className='btn btn-link btn-sm p-0';b.textContent=record.action||'查看详情';b.onclick=()=>Eam.go(record.page,record.query||{});td.append(b);for(const action of record.actions||[]){const extra=document.createElement('button');extra.type='button';extra.className='btn btn-link btn-sm p-0';extra.textContent=action.label;extra.disabled=action.disabled;extra.onclick=action.run;td.append(extra);}tr.append(td);rows.append(tr);}find('list-empty').hidden=filtered.length>0;text('list-count',EamUiComponents.paginationText(filtered.length,page,pages));text('list-total',records.length);text('list-pending',records.filter(r=>!['complete','closed','cancelled','withdrawn','archived','removed','disabled'].includes(r.status)).length);find('list-prev').disabled=page===1;find('list-next').disabled=page===pages;EamUiComponents.pagination(find('list-count').parentElement,{page,pages,total:filtered.length,pageSize:5,countId:'list-count',previousId:'list-prev',nextId:'list-next',onChange:nextPage=>{page=nextPage;render();}});EamUiComponents.syncTableState(rows.closest('table'));}
 for(const id of ['list-search','list-status','list-mine'])find(id).addEventListener(id==='list-search'?'input':'change',()=>{page=1;render();});find('list-reset').onclick=()=>{find('list-search').value='';select.value='';find('list-mine').checked=false;page=1;render();};find('list-prev').onclick=()=>{page--;render();};find('list-next').onclick=()=>{page++;render();};const primary=find('list-primary');primary.textContent=options.primary;primary.disabled=options.allowed===false;primary.onclick=()=>Eam.go(options.page,options.query||{});find('list-mine-label').hidden=!options.mine;render();};
